<?php include "../auth/cek_login.php";include "../koneksi.php";$kat=mysqli_query($conn,"SELECT * FROM kategori");if(isset($_POST['simpan'])){mysqli_query($conn,"INSERT INTO barang(kode_barang,nama_barang,id_kategori,harga_sewa,stok,kondisi) VALUES ('$_POST[kode]','$_POST[nama]','$_POST[kategori]','$_POST[harga]','$_POST[stok]','$_POST[kondisi]')");header("Location:index.php");exit;} ?><!doctype html><html><head><title>Tambah Barang</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Tambah Barang</h1><form method="post"><input name="kode" placeholder="Kode Barang" required><input name="nama" placeholder="Nama Barang" required><select name="kategori" required><option value="">Kategori</option><?php while($k=mysqli_fetch_assoc($kat)):?><option value="<?=$k['id']?>"><?=$k['nama_kategori']?></option><?php endwhile;?></select><input type="number" name="harga" placeholder="Harga sewa/hari" required><input type="number" name="stok" placeholder="Stok" required><select name="kondisi"><option>Baik</option><option>Rusak Ringan</option><option>Rusak</option></select><button name="simpan">Simpan</button></form></div></body></html>